    return df[keep].reset_index(drop=True)

def implied_vol(price, S, K, r, T, kind="call", q=0.0):
    """Volatility at which bs_price matches price; NaN when none fits."""
    if kind == "call":
        lo_b, hi_b = max(S * exp(-q * T) - K * exp(-r * T), 0.0), S * exp(-q * T)
    else:
        lo_b, hi_b = max(K * exp(-r * T) - S * exp(-q * T), 0.0), K * exp(-r * T)
    if not (lo_b < price < hi_b):
        return float("nan")
    lo, hi = 1e-4, 5.0
    for _ in range(100):
        m = (lo + hi) / 2
        if bs_price(S, K, r, m, T, kind, q) > price:
            hi = m
        else:
            lo = m
    return (lo + hi) / 2

def quotes(rows):
    """A hand-made chain: rows of [T, strike, type, bid, ask, volume, age_min]."""
    return pd.DataFrame(rows, columns=["T", "strike", "type", "bid", "ask", "volume", "age_min"])

def vol_quotes(S, r, q, T, strikes, kinds, vol_bid, vol_ask):
    """A chain whose bid and ask are bs_price at two known vols."""
    rows = [[T, K, k, bs_price(S, K, r, vol_bid, T, k, q), bs_price(S, K, r, vol_ask, T, k, q), 1, 0.0]
            for K, k in zip(strikes, kinds)]
    return quotes(rows)

def otm_quotes(df_T, F):
    keep = (((df_T["type"] == "put") & (df_T["strike"] < F))
            | ((df_T["type"] == "call") & (df_T["strike"] >= F)))
    return df_T[keep].sort_values("strike").reset_index(drop=True)

chain = make_chain()
clean = clean_quotes(chain)
